#include <iostream>
#include <optional>
std::optional<char> grade_for(int score) {
    if (score < 0 || score > 100) return std::nullopt;
    if (score >= 90) return 'A';
    if (score >= 80) return 'B';
    if (score >= 70) return 'C';
    if (score >= 60) return 'D';
    return 'F';
}
int main() {
    if (auto grade = grade_for(86)) std::cout << *grade << '\n';
    else std::cout << "invalid score\n";
}
